package com.amber.launcher;

import android.graphics.*;
import android.graphics.drawable.ColorDrawable;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.util.*;

/** Same-window overlay: a native drag continues to home when this overlay is hidden. */
final class AppDrawer extends FrameLayout {
    final MainActivity host;
    final Workspace.Item folder;
    final ArrayList<MainActivity.App> visible=new ArrayList<>();
    GridView grid;
    EditText search;
    TextView heading,info,searchToggle,allTab,favTab,bubble;
    LinearLayout body,header,rail,styles;
    BaseAdapter adapter;
    String query="";
    boolean favorites=false,usage=false,searching=false,manage=false;
    int insetTop,insetBottom;
    final Paint paint=new Paint(3);
    AppDrawer(MainActivity h,Workspace.Item f){super(h);host=h;folder=f;setWillNotDraw(false);setClickable(true);setFocusableInTouchMode(true);build();setOnApplyWindowInsetsListener((v,i)->{insetTop=i.getSystemWindowInsetTop();insetBottom=i.getSystemWindowInsetBottom();body.setPadding(host.dp(18),insetTop+host.dp(8),host.dp(12),insetBottom+host.dp(8));return i;});requestApplyInsets();}
    @Override protected void onDraw(Canvas c){super.onDraw(c);host.home.wallpaper(c,getWidth(),getHeight());paint.setColor((Math.round(host.opacity()*2.55f)<<24)|(host.surface()&0xffffff));c.drawRect(0,0,getWidth(),getHeight(),paint);}
    TextView action(String glyph,String description){TextView t=host.text(glyph,25,host.ink());t.setGravity(Gravity.CENTER);t.setContentDescription(description);t.setMinWidth(host.dp(42));return t;}
    void build(){removeAllViews();body=new LinearLayout(host);body.setOrientation(1);body.setPadding(host.dp(18),insetTop+host.dp(8),host.dp(12),insetBottom+host.dp(8));addView(body,new FrameLayout.LayoutParams(-1,-1));
        header=new LinearLayout(host);header.setGravity(Gravity.CENTER_VERTICAL);
        heading=host.text(folder==null?"All apps":folder.name,26,host.ink());heading.setSingleLine();heading.setEllipsize(TextUtils.TruncateAt.END);heading.setTypeface(Typeface.DEFAULT,Typeface.BOLD);header.addView(heading,new LinearLayout.LayoutParams(0,host.dp(54),1));
        search=new EditText(host);search.setTextColor(host.ink());search.setHintTextColor(host.secondary());search.setHint(folder==null?"Search apps":"Search folder");search.setTextSize(18);search.setSingleLine();search.setBackgroundColor(Color.TRANSPARENT);search.setPadding(0,0,0,0);search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);search.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);search.setVisibility(GONE);header.addView(search,new LinearLayout.LayoutParams(0,host.dp(54),1));
        searchToggle=action("⌕","Search apps");header.addView(searchToggle,new LinearLayout.LayoutParams(host.dp(42),host.dp(48)));searchToggle.setOnClickListener(v->toggleSearch());
        TextView more=action("⋮","More options");header.addView(more,new LinearLayout.LayoutParams(host.dp(42),host.dp(48)));more.setOnClickListener(v->options());TextView close=action("×","Back to home");header.addView(close,new LinearLayout.LayoutParams(host.dp(42),host.dp(48)));close.setOnClickListener(v->host.closeDrawer());body.addView(header);
        info=host.text("",12,host.secondary());body.addView(info,new LinearLayout.LayoutParams(-1,host.dp(27)));
        if(folder==null){LinearLayout tabs=new LinearLayout(host);tabs.setPadding(0,host.dp(3),0,host.dp(8));allTab=tab("All",tabs);favTab=tab("Favorites",tabs);allTab.setOnClickListener(v->{favorites=false;refresh();});favTab.setOnClickListener(v->{favorites=true;refresh();});body.addView(tabs);}else{
            styles=new LinearLayout(host);styles.setPadding(0,host.dp(5),0,host.dp(12));String[] names={"Small","Big","Vertical"},keys={"small","big","vertical"};for(int n=0;n<3;n++){final String key=keys[n];TextView t=tab(names[n],styles);t.setTag(key);t.setOnClickListener(v->{host.board.style(folder,key);host.home.page=folder.page;host.home.invalidate();refresh();});}body.addView(styles);
        }
        FrameLayout area=new FrameLayout(host);body.addView(area,new LinearLayout.LayoutParams(-1,0,1));grid=new GridView(host);grid.setNumColumns(host.prefs.getInt("columns",4));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setVerticalSpacing(host.dp(7));grid.setHorizontalSpacing(host.dp(3));grid.setVerticalScrollBarEnabled(false);grid.setClipToPadding(false);grid.setPadding(0,host.dp(6),0,host.dp(12));grid.setSelector(new ColorDrawable(Color.TRANSPARENT));FrameLayout.LayoutParams gp=new FrameLayout.LayoutParams(-1,-1);gp.rightMargin=folder==null?host.dp(23):0;area.addView(grid,gp);
        TextView empty=host.text("",15,host.secondary());empty.setGravity(Gravity.CENTER);empty.setPadding(host.dp(20),0,host.dp(30),0);empty.setTag("empty");area.addView(empty,new FrameLayout.LayoutParams(-1,-1));grid.setEmptyView(empty);
        if(folder==null){rail=new LinearLayout(host){@Override public boolean onInterceptTouchEvent(MotionEvent e){return true;}};rail.setOrientation(1);rail.setPadding(0,host.dp(8),0,host.dp(8));rail.setBackground(host.rounded((host.ink()&0xffffff)|0x0c000000,14));FrameLayout.LayoutParams rp=new FrameLayout.LayoutParams(host.dp(22),-1,Gravity.RIGHT);rp.topMargin=host.dp(8);rp.bottomMargin=host.dp(8);area.addView(rail,rp);for(char ch='A';ch<='Z';ch++){TextView letter=host.text(String.valueOf(ch),10,host.secondary());letter.setGravity(Gravity.CENTER);letter.setContentDescription("Jump to "+ch);final String key=String.valueOf(ch);letter.setOnClickListener(v->jump(key));rail.addView(letter,new LinearLayout.LayoutParams(-1,0,1));}
            rail.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN||e.getActionMasked()==MotionEvent.ACTION_MOVE){int n=Math.max(0,Math.min(25,(int)(26*e.getY()/Math.max(1,v.getHeight()))));jump(String.valueOf((char)('A'+n)));return true;}bubble.setVisibility(GONE);return true;});
        }
        bubble=host.text("",36,host.ink());bubble.setGravity(Gravity.CENTER);bubble.setBackground(host.rounded(host.surface(),22));bubble.setVisibility(GONE);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(host.dp(70),host.dp(70),Gravity.CENTER);area.addView(bubble,bp);
        adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int p){return visible.get(p);}public long getItemId(int p){return p;}public View getView(int p,View reused,ViewGroup parent){LinearLayout cell;if(reused instanceof LinearLayout)cell=(LinearLayout)reused;else{cell=new LinearLayout(host);cell.setOrientation(1);cell.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);cell.setPadding(host.dp(2),host.dp(4),host.dp(2),0);ImageView icon=new ImageView(host);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);cell.addView(icon,new LinearLayout.LayoutParams(host.dp(54),host.dp(54)));TextView label=host.text("",12,host.ink());label.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);label.setMaxLines(2);label.setEllipsize(TextUtils.TruncateAt.END);label.setIncludeFontPadding(false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,host.dp(35));lp.topMargin=host.dp(8);cell.addView(label,lp);cell.setLayoutParams(new AbsListView.LayoutParams(-1,host.dp(104)));}MainActivity.App a=visible.get(p);((ImageView)cell.getChildAt(0)).setImageBitmap(a.icon);TextView label=(TextView)cell.getChildAt(1);label.setText(a.label);label.setTextColor(host.ink());cell.setContentDescription(a.label+". Hold to drag to home.");return cell;}};
        grid.setAdapter(adapter);grid.setOnItemClickListener((p,v,n,id)->{MainActivity.App a=visible.get(n);if(manage)host.appMenu(a,folder);else{host.launch(a);host.closeDrawer();}});grid.setOnItemLongClickListener((p,v,n,id)->{MainActivity.App a=visible.get(n);host.startDrag(v,new MainActivity.DragData(host.appId(a),null,folder==null?null:folder.id));return true;});
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){query=s.toString();refresh();}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((v,action,event)->{if(!visible.isEmpty()){host.launch(visible.get(0));host.closeDrawer();}return true;});search.setText(query);refresh();
    }
    TextView tab(String label,LinearLayout parent){TextView t=host.text(label,13,host.ink());t.setGravity(Gravity.CENTER);t.setPadding(host.dp(16),0,host.dp(16),0);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,host.dp(35));lp.rightMargin=host.dp(8);parent.addView(t,lp);return t;}
    void toggleSearch(){searching=!searching;heading.setVisibility(searching?GONE:VISIBLE);search.setVisibility(searching?VISIBLE:GONE);searchToggle.setText(searching?"×":"⌕");searchToggle.setContentDescription(searching?"Close search":"Search apps");InputMethodManager imm=(InputMethodManager)host.getSystemService(android.content.Context.INPUT_METHOD_SERVICE);if(searching){search.requestFocus();imm.showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);}else{search.setText("");imm.hideSoftInputFromWindow(search.getWindowToken(),0);requestFocus();}}
    void refresh(){if(adapter==null)return;String q=query.trim().toLowerCase(Locale.ROOT);Set<String> hidden=host.prefs.getStringSet("hidden",Collections.emptySet()),favs=host.prefs.getStringSet("favorites",Collections.emptySet());visible.clear();for(MainActivity.App a:host.apps){String id=host.appId(a);if((folder!=null?folder.members.contains(id):!hidden.contains(id))&&(!favorites||favs.contains(id))&&(a.label.toLowerCase(Locale.ROOT).contains(q)||a.pkg.toLowerCase(Locale.ROOT).contains(q)))visible.add(a);}
        if(usage)Collections.sort(visible,(a,b)->Integer.compare(host.prefs.getInt("use:"+host.appId(b),0),host.prefs.getInt("use:"+host.appId(a),0)));
        heading.setText(folder==null?"All apps":folder.name);info.setText(manage?"Tap an app for options":visible.size()+" apps  ·  Hold & drag to home");
        TextView empty=(TextView)findViewWithTag("empty");if(empty!=null)empty.setText(host.loadingApps?"Loading apps…":!query.isEmpty()?"No matching apps":folder!=null?"Folder is empty\nAdd apps from the menu or drag onto it":favorites?"No favorites yet\nUse Manage apps to choose favorites":"No apps to show");
        if(folder==null){allTab.setBackground(host.rounded((host.ink()&0xffffff)|(!favorites?0x25000000:0x08000000),14));favTab.setBackground(host.rounded((host.ink()&0xffffff)|(favorites?0x25000000:0x08000000),14));allTab.setTypeface(Typeface.DEFAULT,!favorites?Typeface.BOLD:Typeface.NORMAL);favTab.setTypeface(Typeface.DEFAULT,favorites?Typeface.BOLD:Typeface.NORMAL);}else for(int n=0;n<styles.getChildCount();n++){View v=styles.getChildAt(n);v.setBackground(host.rounded((host.ink()&0xffffff)|(folder.style.equals(v.getTag())?0x28000000:0x08000000),14));}
        adapter.notifyDataSetChanged();invalidate();
    }
    void jump(String key){if(usage){usage=false;refresh();}for(int n=0;n<visible.size();n++)if(visible.get(n).label.toUpperCase(Locale.ROOT).compareTo(key)>=0){grid.setSelection(n);break;}bubble.setText(key);bubble.setVisibility(VISIBLE);host.handler.removeCallbacks(hideBubble);host.handler.postDelayed(hideBubble,650);}
    final Runnable hideBubble=()->{if(bubble!=null)bubble.setVisibility(GONE);};
    void refreshTheme(){int first=grid.getFirstVisiblePosition();boolean wasSearching=searching;searching=false;build();grid.setSelection(first);if(wasSearching){searching=true;heading.setVisibility(GONE);search.setVisibility(VISIBLE);searchToggle.setText("×");}invalidate();}
    void options(){if(folder!=null){host.sheet(folder.name,new String[]{"Rename folder","Edit apps","Manage apps","Background & opacity","Remove folder"},n->{if(n==0)host.rename(folder);if(n==1)host.editFolder(folder);if(n==2){manage=!manage;refresh();}if(n==3)host.appearance();if(n==4){host.board.remove(folder);host.closeDrawer();}});return;}
        host.sheet("Drawer",new String[]{manage?"Done managing":"Manage apps","Sort apps","Grid size","Background & opacity","Hidden apps","Home settings"},n->{if(n==0){manage=!manage;refresh();}if(n==1)host.sheet("Sort",new String[]{"A–Z","Most used"},x->{usage=x==1;refresh();});if(n==2)host.sheet("Grid",new String[]{"4 columns","5 columns"},x->{host.prefs.edit().putInt("columns",x==0?4:5).apply();grid.setNumColumns(x==0?4:5);});if(n==3)host.appearance();if(n==4)host.pickApps("Hidden apps",new HashSet<>(host.prefs.getStringSet("hidden",Collections.emptySet())),ids->{host.prefs.edit().putStringSet("hidden",ids).apply();refresh();});if(n==5)host.settings();});
    }
}
